export class GraphBasedDebugger {
  constructor() {
    this.graph = new Map();
  }

  addNode(module, error, correction) {
    if (!this.graph.has(module)) this.graph.set(module, []);
    this.graph.get(module).push({ error, correction });
  }

  prioritizeCorrections(module) {
    const nodes = this.graph.get(module) || [];
    return nodes.sort((a, b) => b.confidence - a.confidence);
  }

  refineStrategies(feedback) {
    feedback.forEach(({ module, error, correction, confidence }) => {
      this.addNode(module, error, correction);
      this.graph.get(module).forEach(node => {
        if (node.error === error && node.correction === correction) {
          node.confidence = confidence;
        }
      });
    });
  }
}